package com.shiphappens.logistics.entity;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="tracking_events") public class TrackingEvent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="shipment_id") private Shipment shipment; @Column(name="event_type") private String eventType; private String status,description,location; @Column(name="created_by") private String createdBy; @Column(name="created_at") private Instant createdAt; @PrePersist void created(){createdAt=Instant.now();} public Long getId(){return id;} @JsonIgnore public Shipment getShipment(){return shipment;} public void setShipment(Shipment v){shipment=v;} public String getEventType(){return eventType;} public void setEventType(String v){eventType=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getLocation(){return location;} public void setLocation(String v){location=v;} public Instant getCreatedAt(){return createdAt;} }
